// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        address ownerBefore = c.owner();

        vm.prank(actor);
        bool success;
        try c.setOwner(address(0xdead)) returns (bool ok) {
            success = ok;
        } catch {
            success = false;
        }

        assertTrue(success == false || c.owner() == ownerBefore);
    }
}
